export const getTodosOsTimes = () => {
  return [
    ...(dbTimes.ESP || []),
    ...(dbTimes.BRA || []),
    ...(dbTimes.ARG || []),
    ...(dbTimes.COL || []),
    ...(dbTimes.CHI || []),
    ...(dbTimes.USA || []),
    ...(dbTimes.MEX || []),
    ...(dbTimes.CAN || []),
    ...(dbTimes.FRA || []),
    ...(dbTimes.ENG || []),
    ...(dbTimes.ALE || []),
    ...(dbTimes.ITA || []),
    ...(dbTimes.Europeu || []),
    ...(dbTimes.CentroNorteamericanos || []),
    ...(dbTimes.Sulamericanos || []),
    ...(dbTimes.RDM || [])
  ];
};

export const getTimesPorDivisao = (divisao) => {
  const todos = getTodosOsTimes();

  if (!divisao) return todos.filter(t => t.div === "Brasileirão Feminino Série A1");

  if (divisao === "BRA_A2") return todos.filter(t => t.div === "Brasileirão Feminino Série A2");
  if (divisao === "ARG_YPF") return todos.filter(t => t.div === "Campeonato Femenino YPF");
  if (divisao === "COL_LFBD") return todos.filter(t => t.div === "Liga Femenina BetPlay Dimayor");
  if (divisao === "CHI_LF") return todos.filter(t => t.div === "Liga Femenina de Chile");
  if (divisao === "USA_NWSL") return todos.filter(t => t.div === "NWSL");
  if (divisao === "MEX_LF") return todos.filter(t => t.div === "Liga Feminil BBVA");
  if (divisao === "CAN_NSL") return todos.filter(t => t.div === "NSL");
  if (divisao === "ENG_WSL") return todos.filter(t => t.div === "Women's Super League");
  if (divisao === "ENG_WSL2") return todos.filter(t => t.div === "Women's Super League 2");
  if (divisao === "ITA_SA") return todos.filter(t => t.div === "Serie A Woman");
  if (divisao === "ESP_LF") return todos.filter(t => t.div === "Liga F Moeve");
  if (divisao === "FRA_ARK") return todos.filter(t => t.div === "Arkema Première Ligue");
  if (divisao === "ALE_GFB") return todos.filter(t => t.div === "Google Pixel Frauen-Bundesliga")
  if (divisao === "CONMEBOL") return todos.filter(t => t.div === "CONMEBOL");
  if (divisao === "UEFA") return todos.filter(t => t.div === "UEFA");
  if (divisao === "CONCACAF") return todos.filter(t => t.div === "CONCACAF");
  
  return todos.filter(t => t.div === "Brasileirão Feminino Série A1"); // Padrão
};

export const getForcaTime = (nomeTime) => {
  const time = getTodosOsTimes().find(
    (t) => t.nome.toLowerCase().trim() === nomeTime.toLowerCase().trim()
  );
  if (!time) return 50;
  if (time.tier === "alto") return 76;
  if (time.tier === "medio") return 62;
  return 48; // baixo
};